package com.eduplay.backend.progress.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.UUID;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.NoArgsConstructor;
import org.hibernate.annotations.Immutable;

/**
 * Append-only record of one played mini-game. The id is generated by the Unity client so that
 * re-uploading the same queued result is a no-op. Inserts go through the SyncRepository.
 */
@Entity
@Immutable
@Table(name = "game_results")
@Getter
@NoArgsConstructor(access = AccessLevel.PROTECTED)
public class GameResult {

    @Id
    private UUID id;

    @Column(name = "child_id", nullable = false)
    private UUID childId;

    @Column(name = "grade_id", nullable = false, length = 32)
    private String gradeId;

    @Column(name = "section_id", nullable = false, length = 64)
    private String sectionId;

    @Column(name = "topic_id", nullable = false, length = 64)
    private String topicId;

    @Column(name = "lesson_id", nullable = false, length = 64)
    private String lessonId;

    @Column(name = "game_index", nullable = false)
    private int gameIndex;

    @Column(name = "game_type", nullable = false, length = 64)
    private String gameType;

    @Column(nullable = false)
    private int score;

    @Column(nullable = false)
    private int attempts;

    @Column(nullable = false)
    private int mistakes;

    @Column(name = "duration_seconds", nullable = false)
    private int durationSeconds;

    @Column(nullable = false)
    private boolean completed;

    @Column(name = "played_at", nullable = false)
    private Instant playedAt;

    @Column(name = "received_at", nullable = false)
    private Instant receivedAt;
}
